// helper: reset was released (high) at the previous rising edge
logic rst_q = 1'b0;
always_ff @(posedge i_clk_core) rst_q <= i_rst_n_core;

// CHK-010: Output values while reset is asserted (BR-3-30, BR-3-31, BR-3-21, BR-7.3-02, BR-7.3-03, BR-6.2-03, BR-6.2-06, BR-6.2-15, BR-14.1-03)
a_CHK_010: assert property (@(posedge i_clk_core)
  (!i_rst_n_core) |-> (o_tlul_a_valid == 1'b0 && o_tlul_d_ready == 1'b0 && o_apb_pready == 1'b0 &&
                       o_apb_prdata == 32'h0 && o_apb_pslverr == 1'b0 && o_tlul_a_opcode == 3'b000 &&
                       o_tlul_a_address == '0 && o_tlul_a_data == 32'h0))
  else begin fails_CHK_010++; $display("NNC_FAIL CHK-010 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!i_rst_n_core) hits_CHK_010 <= hits_CHK_010 + 1;

// CHK-011: o_tlul_d_ready is 1 from the first edge after reset release (BR-3-21, BR-3-22, BR-6.2-15, BR-15.3-06, BR-20-11, BR-5.3-04)
a_CHK_011: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  rst_q |-> (o_tlul_d_ready == 1'b1))
  else begin fails_CHK_011++; $display("NNC_FAIL CHK-011 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (rst_q)) hits_CHK_011 <= hits_CHK_011 + 1;
